-- T068 — the verification call's day and outcome (FR-161; owner's decisions 2026-10-22, the conflict
-- check of batch B13). Generated by `prisma migrate diff --from-config-datasource --to-schema
-- prisma/schema --script` against a database holding every migration before it.
--
-- What it lands: `teacher_profiles.verification_call_outcome`, a new nullable enum `suitable ·
-- unsuitable`, which no column held while FR-161 and `applications.recordCall` name it; and the call's
-- moment as a calendar day, `verification_call_completed_on date`, in place of
-- `verification_call_completed_at timestamptz`: a call is known by its day, and a midnight stored
-- as an instant reads as another day in another zone. Nothing wrote the old column (`recordCall` is
-- this batch's), so it held only nulls and is dropped rather than converted.
--
-- And `verification_request_status` gains `replaced` (B13b review, follow-up 1, owner's decision
-- 2026-10-22): a request for another document closes the request as `replaced`, keeping the
-- document it held, and opens a new one; so the documents sweep (T093) never removes a document an
-- administrator turned away.

-- AlterEnum
ALTER TYPE "verification_request_status" ADD VALUE 'replaced';

-- CreateEnum
CREATE TYPE "verification_call_outcome" AS ENUM ('suitable', 'unsuitable');

-- AlterTable
ALTER TABLE "teacher_profiles" DROP COLUMN "verification_call_completed_at",
ADD COLUMN     "verification_call_completed_on" DATE,
ADD COLUMN     "verification_call_outcome" "verification_call_outcome";
